'use strict';
function renderImportedTrip(){document.querySelector('.home-city').textContent=chatTrip.destination;const homeTags=document.querySelector('.home-tags'),tripTags=document.querySelector('.trip-tags');homeTags.replaceChildren();tripTags.replaceChildren();for(const style of chatTrip.styles){for(const host of [homeTags,tripTags]){const tag=document.createElement('span');tag.textContent=style;host.append(tag)}}document.querySelector('.home-activity').textContent=chatTrip.days+'天出行 · 已同步穿搭偏好';document.querySelector('.home-dates').textContent=chatTrip.departure.replaceAll('-','.')+' — '+chatTrip.returnDate.replaceAll('-','.');document.querySelector('.trip .city').textContent='⌖ '+chatTrip.destination;document.querySelector('.trip summary>span:nth-child(2)').textContent=chatTrip.departure.slice(5)+' — '+chatTrip.returnDate.slice(5);document.querySelector('.trip-expanded').textContent=chatTrip.days+'天旅行 · 目的地：'+chatTrip.destination+'；风格：'+(chatTrip.styles.join('、')||'未选择');}
renderImportedTrip();const demoNote=document.createElement('p');demoNote.className='chat-demo-note';demoNote.textContent='穿搭对话演示';document.querySelector('.composer-wrap').append(demoNote);
document.addEventListener('click',event=>{const button=event.target.closest('[data-save-look]');if(!button)return;const day=Number(button.dataset.saveLook),image=button.dataset.lookImage;if(!Number.isInteger(day)||day<1||day>chatTrip.days||!['look1','look2','look3','day3','day4','pack1','pack2','pack3','colorful'].includes(image))return;window.parent.postMessage({type:'ootrip:chat-apply-look',day,image},'*')});
// Mouse dragging matches the parent app's swipeable day cards.
let drag=null;document.addEventListener('pointerdown',event=>{const rail=event.target.closest('.carousel');if(!rail||event.pointerType==='touch'||event.button!==0)return;drag={rail,x:event.clientX,left:rail.scrollLeft,id:event.pointerId,moved:false}});document.addEventListener('pointermove',event=>{if(!drag)return;const dx=event.clientX-drag.x;if(Math.abs(dx)>5){drag.moved=true;drag.rail.classList.add('is-dragging');drag.rail.setPointerCapture(event.pointerId);drag.rail.scrollLeft=drag.left-dx;event.preventDefault()}});let suppressClick=false;document.addEventListener('pointerup',()=>{if(!drag)return;suppressClick=drag.moved;drag.rail.classList.remove('is-dragging');drag=null;setTimeout(()=>suppressClick=false,200)});document.addEventListener('click',event=>{if(suppressClick){event.preventDefault();event.stopImmediatePropagation()}},true);
